class Solution {
  private static class Node {
    Map<String, Node> children = new TreeMap<>();
    String signature = "";
    boolean deleted;
  }

  public List<List<String>> deleteDuplicateFolder(List<List<String>> paths) {
    Node root = new Node();
    for (List<String> path : paths) {
      Node cur = root;
      for (String name : path) cur = cur.children.computeIfAbsent(name, k -> new Node());
    }
    Map<String, Integer> count = new HashMap<>();
    sign(root, count);
    mark(root, count);
    List<List<String>> result = new ArrayList<>();
    collect(root, new ArrayList<>(), result);
    return result;
  }

  // serialise each subtree; empty folders have an empty signature and are never duplicates
  private String sign(Node node, Map<String, Integer> count) {
    StringBuilder sb = new StringBuilder();
    for (Map.Entry<String, Node> e : node.children.entrySet()) {
      sb.append('(').append(e.getKey()).append(sign(e.getValue(), count)).append(')');
    }
    node.signature = sb.toString();
    if (!node.signature.isEmpty()) count.merge(node.signature, 1, Integer::sum);
    return node.signature;
  }

  private void mark(Node node, Map<String, Integer> count) {
    for (Node child : node.children.values()) {
      child.deleted = !child.signature.isEmpty() && count.get(child.signature) > 1;
      if (!child.deleted) mark(child, count);
    }
  }

  private void collect(Node node, List<String> path, List<List<String>> out) {
    for (Map.Entry<String, Node> e : node.children.entrySet()) {
      Node child = e.getValue();
      if (child.deleted) continue;
      path.add(e.getKey());
      out.add(new ArrayList<>(path));
      collect(child, path, out);
      path.remove(path.size() - 1);
    }
  }
}
